class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        if k > len(s):
            return False

        # Iterate through each possible starting position of a substring of length k
        for i in range(len(s) - k + 1):
            # Check if the substring s[i:i+k] consists of only one distinct character
            char = s[i]
            if all(c == char for c in s[i:i+k]):
                # Check if the character before the substring is different (if it exists)
                if i > 0 and s[i-1] == char:
                    continue
                # Check if the character after the substring is different (if it exists)
                if i + k < len(s) and s[i+k] == char:
                    continue

                # If we reach here, we found a valid substring
                return True

        return False
