from typing import List

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        # Build adjacency list for the graph
        adj = [[] for _ in range(n)]

        # For each pair of nodes (i, j) where i != j
        for i in range(n):
            for j in range(n):
                if i != j:
                    # Calculate intersection of properties[i] and properties[j]
                    intersection = 0
                    for x in properties[i]:
                        if x in properties[j]:
                            intersection += 1

                    # If intersection count >= k, add edge between i and j
                    if intersection >= k:
                        adj[i].append(j)
                        adj[j].append(i)

        # Count connected components using BFS
        visited = [False] * n
        components = 0

        for i in range(n):
            if not visited[i]:
                components += 1
                queue = [i]
                visited[i] = True
                while queue:
                    node = queue.pop(0)
                    for neighbor in adj[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            queue.append(neighbor)

        return components
