    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        total_sum = 0
        n = len(nums)

        for i in range(n):
            left_index = i - k
            right_index = i + k

            # If either index is out of bounds, the element is considered good
            if left_index < 0 or right_index >= n:
                total_sum += nums[i]
            else:
                # Check if element is strictly greater than both neighbors
                if nums[i] > nums[left_index] and nums[i] > nums[right_index]:
                    total_sum += nums[i]

