class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        if n == 0:
            return 0

        # Build adjacency list for the graph
        adj = [[] for _ in range(n)]

        # For each pair of nodes, check if they share at least k elements
        for i in range(n):
            for j in range(n):
                if i != j:
                    # Count common elements between properties[i] and properties[j]
                    intersection = set(properties[i]) & set(properties[j])
                    if len(intersection) >= k:
                        adj[i].append(j)
                        adj[j].append(i)

        # Count connected components using BFS
        visited = [False] * n
        components = 0

        for i in range(n):
            if not visited[i]:
                components += 1
                queue = deque([i])
                while queue:
                    node = queue.popleft()
                    for neighbor in adj[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            queue.append(neighbor)

        return components
