    input_data = sys.stdin.read().split()

    if not input_data:
        return

    # Convert to integers
    A = [int(x) for x in input_data]

    # Count frequency of each card value
    from collections import Counter
    counts = Counter(A)

    # Check if we can form a full house
    # A full house requires 3 cards of one value and 2 cards of another
    possible = False
    for count in counts.values():
        if count >= 3:
            # If a value appears at least 3 times, check if any other value appears at least 2 times
            if any(counts[v] >= 2 for v in counts if v != A.count(count)):
                possible = True
                break

    # More direct check
    possible = False
    for count in counts.values():
        if count >= 3:
            # Check if any other value appears at least 2 times
            if any(counts[v] >= 2 for v in counts if v != count):
                possible = True
                break

    if possible:
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()
